export default async function window(_input, context) {
  const until = Date.now(),
    saved = await context.state.get("last-company-run");
  let since = saved;
  if (since == null) {
    since = until;
    await context.state.set("last-company-run", since);
  }
  if (!Number.isSafeInteger(since) || since < 0 || since > until)
    throw Error("Invalid company watermark");
  return { since, until };
}

