export default function pages({ since, until, previousState, response, statusCode }) {
  let state = previousState ?? { companies: [], seen: [], cursor: null };
  if (!Array.isArray(state.companies) || !Array.isArray(state.seen))
    throw Error("Invalid company progress");
  if (response != null) {
    if (statusCode < 200 || statusCode >= 300 || !response || !Array.isArray(response.results))
      throw Error("Invalid HubSpot list");
    let companies = state.companies;
    for (const c of response.results) {
      if (!c || typeof c.id !== "string" || !c.properties || typeof c.updatedAt !== "string")
        throw Error("Invalid HubSpot company");
      const t = Date.parse(c.updatedAt);
      if (!Number.isFinite(t)) throw Error("Invalid company timestamp");
      if (t >= since && t < until) companies = companies.concat([c]);
    }
    const paging = response.paging;
    if (paging != null && (typeof paging !== "object" || Array.isArray(paging)))
      throw Error("Invalid HubSpot paging");
    const next = paging?.next;
    if (
      next != null &&
      (typeof next !== "object" ||
        Array.isArray(next) ||
        typeof next.after !== "string" ||
        !next.after)
    )
      throw Error("Invalid HubSpot cursor");
    const cursor = next?.after ?? null;
    if (cursor != null && (typeof cursor !== "string" || !cursor || state.seen.includes(cursor)))
      throw Error("Invalid HubSpot cursor");
    state = { companies, seen: cursor ? state.seen.concat(cursor) : state.seen, cursor };
  }
  return {
    state,
    more: response == null || state.cursor != null,
    params: {
      limit: 100,
      properties: "name,domain",
      ...(state.cursor ? { after: state.cursor } : {}),
    },
    companies: state.companies,
    hasCompanies: state.companies.length > 0,
    count: 0,
  };
}

