export default function pages({ previousState, organizations, pagination }) {
  let s = previousState ?? { items: [], page: 1 };
  if (!Array.isArray(s.items) || !Number.isInteger(s.page) || s.page < 1)
    throw Error("Invalid organization progress");
  if (organizations != null) {
    if (!Array.isArray(organizations) || !pagination || typeof pagination.hasMore !== "boolean")
      throw Error("Invalid Zendesk page");
    if (pagination.hasMore && s.page >= 100)
      throw Error("Zendesk offset pagination exceeds 100 pages");
    s = { items: s.items.concat(organizations), page: pagination.hasMore ? s.page + 1 : 0 };
  }
  return { state: s, more: organizations == null || s.page > 0, page: s.page || 1, items: s.items };
}

