export default function plan({ companies, organizations }) {
  if (!Array.isArray(companies) || !Array.isArray(organizations)) throw Error("Invalid records");
  const names = new Map();
  for (const o of organizations) {
    if (!o || !Number.isSafeInteger(o.id) || typeof o.name !== "string")
      throw Error("Invalid Zendesk organization");
    let k = o.name.toLowerCase();
    names.set(k, [...(names.get(k) || []), o]);
  }
  const seen = new Set(),
    plans = [];
  for (const c of companies) {
    const name = c.properties?.name,
      domain = c.properties?.domain;
    if (typeof name !== "string" || !name.trim() || typeof domain !== "string" || !domain.trim())
      throw Error("Company name or domain missing");
    let k = name.toLowerCase();
    if (seen.has(k)) throw Error("Duplicate HubSpot company names");
    seen.add(k);
    const matches = names.get(k) || [];
    if (matches.length > 1) throw Error("Duplicate Zendesk organization names");
    plans.push({ id: matches[0]?.id ?? null, name, domain });
  }
  return { plans };
}

