export default function next({ plans, previousState, confirmed }) {
  if (!Array.isArray(plans)) throw Error("Invalid company plans");
  let index = 0;
  if (previousState != null) {
    if (!Number.isInteger(previousState.index) || !confirmed || confirmed.ok !== true)
      throw Error("Organization write not confirmed");
    index = previousState.index;
  }
  if (index >= plans.length)
    return {
      state: { index },
      more: false,
      isCreate: true,
      endpoint: "/api/v2/organizations.json",
      body: {},
      expectedId: null,
      count: index,
    };
  const p = plans[index];
  return {
    state: { index: index + 1 },
    more: true,
    isCreate: p.id === null,
    endpoint:
      p.id === null ? "/api/v2/organizations.json" : "/api/v2/organizations/" + p.id + ".json",
    body: { organization: { name: p.name, domain_names: [p.domain] } },
    expectedId: p.id,
    count: index,
  };
}

