export default function confirm({ statusCode, body, expectedId }) {
  if (
    statusCode < 200 ||
    statusCode >= 300 ||
    !body ||
    !body.organization ||
    !Number.isSafeInteger(body.organization.id)
  )
    throw Error("Zendesk did not confirm organization");
  if (expectedId !== null && body.organization.id !== expectedId)
    throw Error("Zendesk confirmed a different organization");
  return { confirmed: { ok: true } };
}

